// Google Calendar behind the neutral CalendarCapability (E39.3, #601). Permissions (decision record): reads need
// `calendar.readonly`, writes need `calendar.events`.
//
// Two rules of the issue that live here:
//   * `sendUpdates` is set from `notifyAttendees` and is `none` unless the caller asked: an agent must not email people by side effect;
//   * creating an event is idempotent: the event id is generated by the client (from the caller's idempotency key, or random), so a
//     retry after a lost answer finds the same event (409) instead of making a second one.
import { createHash, randomBytes } from 'node:crypto';

import {
  CapabilityError,
  notifyAttendeesOf,
  pageSizeOf,
  type AttendeeInput,
  type BusyBlock,
  type CalendarCapability,
  type CalendarEvent,
  type CalendarInfo,
  type CapabilityContext,
  type DeleteEventOptions,
  type EventPatch,
  type EventQuery,
  type FreeBusyQuery,
  type NewEvent,
  type Page,
} from '../capabilities';
import { GOOGLE } from './google.constants';
import { GoogleHttp, type TokenSource } from './google-http';

interface GEventTime {
  date?: string;
  dateTime?: string;
  timeZone?: string;
}
interface GEvent {
  id: string;
  status?: string;
  summary?: string;
  description?: string;
  location?: string;
  start?: GEventTime;
  end?: GEventTime;
  attendees?: { email?: string; displayName?: string; responseStatus?: string; organizer?: boolean; self?: boolean }[];
  recurringEventId?: string;
  recurrence?: string[];
  hangoutLink?: string;
  htmlLink?: string;
  conferenceData?: { entryPoints?: { uri?: string; entryPointType?: string }[] };
}

const EVENT_FIELDS = 'id,status,summary,description,location,start,end,attendees(email,displayName,responseStatus,organizer),recurringEventId,recurrence,hangoutLink,htmlLink,conferenceData(entryPoints(uri,entryPointType))';

const RESPONSES = ['accepted', 'declined', 'tentative', 'needsAction'] as const;
const ROLES = ['owner', 'writer', 'reader', 'freeBusyReader'] as const;

/** A Calendar event id: base32hex characters (a-v, 0-9), 5 to 1024 long. Derived from the caller's key so a retry finds the same event. */
export function eventIdFor(idempotencyKey?: string): string {
  const bytes = idempotencyKey ? createHash('sha256').update(idempotencyKey).digest().subarray(0, 16) : randomBytes(16);
  // base32hex without padding
  const alphabet = '0123456789abcdefghijklmnopqrstuv';
  let bits = 0;
  let value = 0;
  let out = '';
  for (const b of bytes) {
    value = (value << 8) | b;
    bits += 8;
    while (bits >= 5) {
      out += alphabet[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) out += alphabet[(value << (5 - bits)) & 31];
  return out;
}

const timeOut = (t: GEventTime | undefined): { value: string; allDay: boolean; zone: string | null } | null => {
  if (!t) return null;
  if (t.dateTime) return { value: t.dateTime, allDay: false, zone: t.timeZone ?? null };
  if (t.date) return { value: t.date, allDay: true, zone: t.timeZone ?? null };
  return null;
};

export function toEvent(e: GEvent, calendarId: string): CalendarEvent {
  const start = timeOut(e.start);
  const end = timeOut(e.end);
  if (!start || !end) throw new CapabilityError('PROVIDER_ERROR', { status: 200, reason: 'BAD_EVENT' });
  const status = e.status === 'tentative' || e.status === 'cancelled' ? e.status : 'confirmed';
  return {
    id: e.id,
    calendarId,
    title: e.summary ?? '',
    description: e.description ?? null,
    location: e.location ?? null,
    start: start.value,
    end: end.value,
    allDay: start.allDay,
    timeZone: start.zone,
    status,
    attendees: (e.attendees ?? [])
      .filter((a) => a.email)
      .map((a) => ({ address: a.email!, name: a.displayName ?? null, response: (RESPONSES as readonly string[]).includes(a.responseStatus ?? '') ? (a.responseStatus as (typeof RESPONSES)[number]) : 'needsAction', organizer: a.organizer === true })),
    recurring: !!e.recurringEventId || (e.recurrence?.length ?? 0) > 0,
    conferenceUrl: e.hangoutLink ?? e.conferenceData?.entryPoints?.find((p) => p.entryPointType === 'video')?.uri ?? null,
    webUrl: e.htmlLink ?? null,
  };
}

const timeIn = (value: string, zone?: string): GEventTime => (value.includes('T') ? { dateTime: value, ...(zone ? { timeZone: zone } : {}) } : { date: value });
const attendeesIn = (list: readonly AttendeeInput[]) => list.map((a) => ({ email: a.address, ...(a.name ? { displayName: a.name } : {}) }));

export class GoogleCalendar implements CalendarCapability {
  constructor(
    private readonly ctx: CapabilityContext,
    private readonly http: GoogleHttp,
    private readonly tokens: TokenSource,
  ) {}

  private cal(id?: string): string {
    return encodeURIComponent(id ?? 'primary');
  }

  async listCalendars(): Promise<CalendarInfo[]> {
    const out: CalendarInfo[] = [];
    let pageToken: string | undefined;
    for (let page = 0; page < 10; page++) {
      const res = await this.http.call<{ items?: { id: string; summary?: string; summaryOverride?: string; primary?: boolean; timeZone?: string; accessRole?: string }[]; nextPageToken?: string }>(this.tokens, this.ctx, {
        service: 'calendar',
        op: 'calendarList.list',
        method: 'GET',
        url: `${GOOGLE.calendar}/users/me/calendarList`,
        query: { maxResults: 250, pageToken, fields: 'items(id,summary,summaryOverride,primary,timeZone,accessRole),nextPageToken' },
        idempotent: true,
      });
      for (const c of res.data?.items ?? []) {
        out.push({
          id: c.id,
          name: c.summaryOverride ?? c.summary ?? c.id,
          primary: c.primary === true,
          timeZone: c.timeZone ?? null,
          accessRole: c.accessRole === 'freeBusyReader' ? 'freeBusy' : (ROLES as readonly string[]).includes(c.accessRole ?? '') ? (c.accessRole as 'owner' | 'writer' | 'reader') : 'reader',
        });
      }
      pageToken = res.data?.nextPageToken;
      if (!pageToken) break;
    }
    return out;
  }

  async listEvents(q: EventQuery): Promise<Page<CalendarEvent>> {
    const calendarId = q.calendarId ?? 'primary';
    const res = await this.http.call<{ items?: GEvent[]; nextPageToken?: string }>(this.tokens, this.ctx, {
      service: 'calendar',
      op: 'events.list',
      method: 'GET',
      url: `${GOOGLE.calendar}/calendars/${this.cal(calendarId)}/events`,
      query: { timeMin: q.from, timeMax: q.to, singleEvents: true, orderBy: 'startTime', q: q.text, maxResults: pageSizeOf(q), pageToken: q.pageToken, fields: `items(${EVENT_FIELDS}),nextPageToken` },
      idempotent: true,
    });
    return { items: (res.data?.items ?? []).filter((e) => e.start && e.end).map((e) => toEvent(e, calendarId)), nextPageToken: res.data?.nextPageToken ?? null };
  }

  async freeBusy(q: FreeBusyQuery): Promise<BusyBlock[]> {
    const ids = q.calendarIds ?? ['primary'];
    const res = await this.http.call<{ calendars?: Record<string, { busy?: { start: string; end: string }[] }> }>(this.tokens, this.ctx, {
      service: 'calendar',
      op: 'freeBusy.query',
      method: 'POST',
      url: `${GOOGLE.calendar}/freeBusy`,
      json: { timeMin: q.from, timeMax: q.to, items: ids.map((id) => ({ id })) },
      idempotent: true, // a query: repeating it changes nothing
    });
    return Object.entries(res.data?.calendars ?? {}).flatMap(([calendarId, c]) => (c.busy ?? []).map((b) => ({ calendarId, start: b.start, end: b.end })));
  }

  async createEvent(e: NewEvent): Promise<CalendarEvent> {
    const calendarId = e.calendarId ?? 'primary';
    const id = eventIdFor(e.idempotencyKey);
    const body = {
      id,
      summary: e.title,
      ...(e.description !== undefined ? { description: e.description } : {}),
      ...(e.location !== undefined ? { location: e.location } : {}),
      start: timeIn(e.start, e.timeZone),
      end: timeIn(e.end, e.timeZone),
      ...(e.attendees?.length ? { attendees: attendeesIn(e.attendees) } : {}),
      ...(e.conference === true ? { conferenceData: { createRequest: { requestId: id, conferenceSolutionKey: { type: 'hangoutsMeet' } } } } : {}),
    };
    const res = await this.http.call<GEvent>(this.tokens, this.ctx, {
      service: 'calendar',
      op: 'events.insert',
      method: 'POST',
      url: `${GOOGLE.calendar}/calendars/${this.cal(calendarId)}/events`,
      query: { sendUpdates: notifyAttendeesOf(e) ? 'all' : 'none', conferenceDataVersion: e.conference === true ? 1 : undefined, fields: EVENT_FIELDS },
      json: body,
      idempotent: true, // the id is ours: a retry that finds it (409) means the first attempt worked
      accept: [409],
    });
    if (res.status === 409) {
      // The same id exists: the earlier attempt succeeded. Read it back.
      const got = await this.http.call<GEvent>(this.tokens, this.ctx, { service: 'calendar', op: 'events.get', method: 'GET', url: `${GOOGLE.calendar}/calendars/${this.cal(calendarId)}/events/${id}`, query: { fields: EVENT_FIELDS }, idempotent: true });
      return toEvent(got.data as GEvent, calendarId);
    }
    if (!res.data) throw new CapabilityError('PROVIDER_ERROR', { status: res.status, reason: 'EMPTY' });
    return toEvent(res.data, calendarId);
  }

  async updateEvent(id: string, patch: EventPatch): Promise<CalendarEvent> {
    const calendarId = patch.calendarId ?? 'primary';
    const body: Record<string, unknown> = {};
    if (patch.title !== undefined) body.summary = patch.title;
    if (patch.description !== undefined) body.description = patch.description;
    if (patch.location !== undefined) body.location = patch.location;
    if (patch.start !== undefined) body.start = timeIn(patch.start, patch.timeZone);
    if (patch.end !== undefined) body.end = timeIn(patch.end, patch.timeZone);
    if (patch.attendees !== undefined) body.attendees = attendeesIn(patch.attendees);
    const res = await this.http.call<GEvent>(this.tokens, this.ctx, {
      service: 'calendar',
      op: 'events.patch',
      method: 'PATCH',
      url: `${GOOGLE.calendar}/calendars/${this.cal(calendarId)}/events/${encodeURIComponent(id)}`,
      query: { sendUpdates: notifyAttendeesOf(patch) ? 'all' : 'none', fields: EVENT_FIELDS },
      json: body,
      idempotent: true, // setting fields to values is repeatable
    });
    if (!res.data) throw new CapabilityError('PROVIDER_ERROR', { status: res.status, reason: 'EMPTY' });
    return toEvent(res.data, calendarId);
  }

  async deleteEvent(id: string, opts: DeleteEventOptions): Promise<void> {
    // 410 (gone) means it was already deleted: the goal is met.
    await this.http.call(this.tokens, this.ctx, {
      service: 'calendar',
      op: 'events.delete',
      method: 'DELETE',
      url: `${GOOGLE.calendar}/calendars/${this.cal(opts.calendarId)}/events/${encodeURIComponent(id)}`,
      query: { sendUpdates: notifyAttendeesOf(opts) ? 'all' : 'none' },
      idempotent: true,
      accept: [410],
    });
  }
}
